SELECT so.receiving_time receivingTime, -- 计划送货日期 c.supplier_name supplierName, -- 客户名称 omp.update_time updateTime, -- 送货日期 ifnull(m.materiel_name,omp.materiel_id) materielName, -- 产品名称 ifnull(omp.order_num,0) detailsNum, -- 销售数量 ifnull(omp.materiel_num,0) fulfillNum, -- 已送货数量 ifnull(omp.order_num,0)-ifnull(omp.materiel_num,0) surplusNum, -- 剩余数量 sod.details_remark remark, -- 备注 so.delivery_address address, -- 送货地址 so.order_no orderNo, -- 关联业务 m.files imgPath, -- 图片 so.order_id orderId, so.supplier_id supplierId, p1.handle, m.materiel_id materielId, so.template_id templateId FROM brt_market_order so inner join brt_supplier_receiving sr on sr.order_id = so.order_id inner join brt_market_order_details sod on sod.order_id = so.order_id inner join brt_order_materiel_plan omp on omp.order_details_id = sod.details_id and omp.order_node_id = sr.order_node_id left JOIN brt_materiel m on m.materiel_id = omp.materiel_id left join brt_customer_address ca on ca.customer_id = so.supplier_id and ca.address_type = '1' left join brt_supplier c on so.supplier_id = c.supplier_id left join ( select p.orderId, if(p.orderNum-p.materielNum >0,if(p.materielNum=0,'收货','部分收货'),'全部收货') handle from ( SELECT so.order_id orderId, sum(ifnull( omp.order_num, 0 )) orderNum, sum(ifnull( omp.materiel_num, 0 )) materielNum FROM brt_market_order so INNER JOIN brt_market_order_details sod ON sod.order_id = so.order_id INNER JOIN brt_order_materiel_plan omp ON omp.order_details_id = sod.details_id GROUP BY so.order_id )p ) p1 on p1.orderId = so.order_id
and so.supplier_id = #{receivingRemindVo.supplierId}
and omp.update_time >= str_to_date(#{receivingRemindVo.timeStart},"%Y-%m-%d")
and omp.update_time <= str_to_date(#{receivingRemindVo.timeEnd},"%Y-%m-%d")
and c.supplier_name like concat('%',#{receivingRemindVo.supplierName},'%')
and c.supplier_type = #{receivingRemindVo.supplierType}
and m.materiel_id = #{receivingRemindVo.materielId}
and so.order_no like concat('%',#{receivingRemindVo.orderNo},'%')
and p.handle in
#{item}
and so.delivery_address like concat('%',#{receivingRemindVo.address},'%')
